+func TestLinkFinderFindLinkWithUnicodeCharacters(t *testing.T) {
+	b, err := url.Parse("http://foo.com")
+	assert.Nil(t, err)
+
+	// Test with a URL containing Unicode characters that should be encoded
+	n, err := html.Parse(strings.NewReader(
+		htmlWithBody(`<a href="http://foo.com/café" />`)),
+	)
+	assert.Nil(t, err)
+
+	ls := newTestLinkFinder().Find(n, b)
+
+	// The URL should be properly encoded
+	err, ok := ls["http://foo.com/caf%C3%A9"]
+	assert.True(t, ok)
+	assert.Nil(t, err)
+}
